# usegalaxy.eu

<iframe id="embeddedFrame" src="https://plausible.galaxyproject.eu/share/usegalaxy.eu?auth=pXOfTtSoJyU8y0K75jmrm" width="100%" style="border: none; min-height: 1500px;></iframe>

<script>
var iframe = document.getElementById("embeddedFrame");

function setIframeSize() {
    // Set the iframe height to match its parent's height
    iframe.style.height = iframe.parentElement.offsetHeight + "px";

    // Set the iframe width to match its parent's width
    iframe.style.width = iframe.parentElement.offsetWidth + "px";
}

// Call setIframeSize when the iframe content is loaded
iframe.onload = setIframeSize;

// Also, call setIframeSize when the window is resized
window.addEventListener("resize", setIframeSize);

// Function to refresh the iframe
window.setInterval(function() {
            reloadIFrame()
        }, 30000);

        function reloadIFrame() {
            console.log('reloading..');
            document.getElementById('iframe').contentWindow.location.reload();
        }
</script>
